#!/usr/bin/env python3
"""
PostgreSQL Query Runner using Claude AI as the interface.
This script connects to a PostgreSQL database and runs user-provided SQL queries
through a conversational interface powered by Claude.
"""

import os
import sys
import json
import psycopg2
import psycopg2.extras
from typing import Any
import anthropic

# Database connection configuration
DB_CONFIG = {
    "host": os.environ.get("DB_HOST", "localhost"),
    "port": int(os.environ.get("DB_PORT", "5432")),
    "database": os.environ.get("DB_NAME", "postgres"),
    "user": os.environ.get("DB_USER", "postgres"),
    "password": os.environ.get("DB_PASSWORD", ""),
}

# Initialize Anthropic client
client = anthropic.Anthropic()

def get_db_connection():
    """Create and return a database connection."""
    try:
        conn = psycopg2.connect(**DB_CONFIG)
        return conn
    except psycopg2.Error as e:
        return {"error": f"Failed to connect to database: {str(e)}"}

def execute_query(query: str, params: list = None) -> dict[str, Any]:
    """
    Execute a SQL query and return results.

    Args:
        query: SQL query string
        params: Optional list of parameters for parameterized queries

    Returns:
        Dictionary with results or error information
    """
    # Basic SQL injection prevention - check for dangerous patterns
    dangerous_patterns = [
        "DROP DATABASE",
        "DROP SCHEMA",
        "TRUNCATE",
        "DELETE FROM",
        "DROP TABLE",
    ]

    query_upper = query.upper().strip()
    for pattern in dangerous_patterns:
        if pattern in query_upper:
            return {
                "error": f"Potentially dangerous query detected. Pattern '{pattern}' is not allowed.",
                "query": query
            }

    conn = get_db_connection()
    if isinstance(conn, dict) and "error" in conn:
        return conn

    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cursor:
            if params:
                cursor.execute(query, params)
            else:
                cursor.execute(query)

            # Check if query returns results
            if cursor.description:
                results = cursor.fetchall()
                # Convert RealDictRow objects to regular dicts
                results_list = [dict(row) for row in results]
                return {
                    "success": True,
                    "rows": results_list,
                    "row_count": len(results_list),
                    "columns": [desc[0] for desc in cursor.description]
                }
            else:
                conn.commit()
                return {
                    "success": True,
                    "rows_affected": cursor.rowcount,
                    "message": f"Query executed successfully. {cursor.rowcount} row(s) affected."
                }
    except psycopg2.Error as e:
        conn.rollback()
        return {
            "error": f"Query execution failed: {str(e)}",
            "query": query
        }
    finally:
        conn.close()

def get_table_info(table_name: str = None) -> dict[str, Any]:
    """
    Get information about database tables.

    Args:
        table_name: Optional specific table name, or None for all tables

    Returns:
        Dictionary with table information
    """
    if table_name:
        query = """
            SELECT 
                column_name,
                data_type,
                is_nullable,
                column_default
            FROM information_schema.columns
            WHERE table_schema = 'public' 
            AND table_name = %s
            ORDER BY ordinal_position;
        """
        result = execute_query(query, [table_name])
    else:
        query = """
            SELECT 
                table_name,
                table_type
            FROM information_schema.tables
            WHERE table_schema = 'public'
            ORDER BY table_name;
        """
        result = execute_query(query)

    return result

# Define tools for Claude
tools = [
    {
        "name": "execute_sql_query",
        "description": "Execute a SQL query on the PostgreSQL database. Returns results for SELECT queries or affected row count for other queries. Dangerous operations like DROP DATABASE, DROP SCHEMA, TRUNCATE, DELETE FROM, and DROP TABLE are blocked for safety.",
        "input_schema": {
