]

def process_tool_call(tool_name: str, tool_input: dict) -> str:
    """Process a tool call and return the result as a string."""
    if tool_name == "execute_sql_query":
        query = tool_input.get("query", "")
        params = tool_input.get("params", None)
        result = execute_query(query, params)
        return json.dumps(result, default=str, indent=2)

    elif tool_name == "get_database_info":
        table_name = tool_input.get("table_name", None)
        result = get_table_info(table_name)
        return json.dumps(result, default=str, indent=2)

    else:
        return json.dumps({"error": f"Unknown tool: {tool_name}"})

def run_query_assistant(user_request: str) -> str:
    """
    Run the query assistant with the given user request.
    Uses an agentic loop to handle tool calls.

    Args:
        user_request: The user's query or request

    Returns:
        The assistant's final response
    """
    messages = [
        {
            "role": "user",
            "content": user_request
        }
    ]

    system_prompt = """You are a helpful PostgreSQL database assistant. You help users query and understand their database.

When users ask about data or want to run queries:
1. First check the database structure if needed using get_database_info
2. Execute appropriate SQL queries using execute_sql_query
3. Present results in a clear, readable format
4. Explain what the results mean

Always use parameterized queries when dealing with user-provided values to prevent SQL injection.
Be helpful and explain your queries when appropriate."""

    # Agentic loop
    while True:
        response = client.messages.create(
            model="claude-opus-4-5",
            max_tokens=4096,
            system=system_prompt,
            tools=tools,
            messages=messages
        )

        # Check if we're done
        if response.stop_reason == "end_turn":
            # Extract text from response
            final_text = ""
            for block in response.content:
                if hasattr(block, "text"):
                    final_text += block.text
            return final_text

        # Process tool calls
        if response.stop_reason == "tool_use":
            # Add assistant's response to messages
            messages.append({
                "role": "assistant",
                "content": response.content
            })

            # Process each tool call
            tool_results = []
            for block in response.content:
                if block.type == "tool_use":
                    tool_result = process_tool_call(block.name, block.input)
                    tool_results.append({
                        "type": "tool_result",
                        "tool_use_id": block.id,
                        "content": tool_result
                    })

            # Add tool results to messages
            if tool_results:
                messages.append({
                    "role": "user",
                    "content": tool_results
                })
        else:
            # Unexpected stop reason
            break

    return "Query processing completed."

def main():
    """Main function to run the PostgreSQL query assistant."""
    print("PostgreSQL Query Assistant")
    print("=" * 50)
    print(f"Connecting to: {DB_CONFIG['host']}:{DB_CONFIG['port']}/{DB_CONFIG['database']}")
    print("Type 'exit' or 'quit' to stop")
    print("=" * 50)

    # Test database connection
    test_conn = get_db_connection()
    if isinstance(test_conn, dict) and "error" in test_conn:
        print(f"Warning: {test_conn['error']}")
        print("Continuing anyway - you can still ask questions about SQL syntax")
    else:
        test_conn.close()
        print("Database connection successful!")

    print()

    # Interactive loop
    while True:
        try:
            user_input = input("You: ").strip()

            if not user_input:
                continue

            if user_input.lower() in ["exit", "quit"]:
                print("Goodbye!")
                break

            print("\nAssistant: ", end="", flush=True)
            response = run_query_assistant(user_input)
            print(response)
            print()

        except KeyboardInterrupt:
            print("\n\nInterrupted. Goodbye!")
            break
        except Exception as e:
            print(f"\nError: {str(e)}")
            print("Please try again.")

if __name__ == "__main__":
    main()
